-- Ensure audit log IDs are generated by the existing bigint sequence.
-- Use a timestamp newer than the repository's existing 2026 migrations so
-- migration runners apply this after the audit_logs table is created.
ALTER TABLE public.audit_logs
  ALTER COLUMN id SET DEFAULT nextval('public.audit_logs_id_seq'::regclass);

-- Align the sequence with existing rows before new inserts begin using it.
SELECT setval(
  'public.audit_logs_id_seq'::regclass,
  GREATEST(COALESCE((SELECT MAX(id) FROM public.audit_logs), 0) + 1, 1),
  false
);
